-- S'assurer que la table app_defaults existe (déjà créée à l'étape 1)
CREATE TABLE IF NOT EXISTS public.app_defaults (
  key        text PRIMARY KEY,
  data       jsonb NOT NULL,
  updated_at timestamptz DEFAULT now(),
  label      text
);

-- Activer RLS si pas encore fait
ALTER TABLE public.app_defaults ENABLE ROW LEVEL SECURITY;

-- Policies (idempotentes)
DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE tablename='app_defaults' AND policyname='app_defaults_read_all'
  ) THEN
    CREATE POLICY "app_defaults_read_all" ON public.app_defaults FOR SELECT USING (true);
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE tablename='app_defaults' AND policyname='app_defaults_write_auth'
  ) THEN
    CREATE POLICY "app_defaults_write_auth" ON public.app_defaults FOR ALL USING (true);
  END IF;
END $$;

